"\n"
"/** Is `$n` inside (or equal to) a node with this class? Use"
"d to decide\n"
" *  whether a wheel event is over the explorer. */\n"
"function ide_node_under_class(HNode $n, string $cls): bool {"
"\n"
"    $p = $n;\n"
"    while ($p != null) {\n"
"        if ($p->hasClass($cls)) { return true; }\n"
"        $p = $p->up;\n"
"    }\n"
"    return false;\n"
"}\n"
"\n"
"/** A path as the explorer writes it: relative to the root. "
"*/\n"
"function ide_rel_path(string $root, string $path): string {\n"
"    $r = str_replace(\"\\\\\", \"/\", $root);\n"
"    $p = str_replace(\"\\\\\", \"/\", $path);\n"
"    if (str_starts_with($p, $r . \"/\")) { return substr($p, s"
"trlen($r) + 1); }\n"
"    return $p;\n"
"}\n"
"\n"
"function ide_path_is_dir(string $p): bool {\n"
"    return str_ends_with($p, \"/\");\n"
"}\n"
"\n"
"/** Commands sorted by how well they matched, stable for equ"
"al scores. */\n"
"function ide_cmd_sort([IdeCmd] $hits): [IdeCmd] {\n"
"    $out: [IdeCmd];\n"
"    for ($i = 0; $i < count($hits); $i++) { $out[] = $hits[$"
"i]; }\n"
"    $n = count($out);\n"
"    for ($i = 1; $i < $n; $i++) {\n"
"        $x = $out[$i];\n"
"        $j = $i - 1;\n"
"        while ($j >= 0 && $out[$j]->rank > $x->rank) {\n"
"            $out[$j + 1] = $out[$j];\n"
"            $j = $j - 1;\n"
"        }\n"
"        $out[$j + 1] = $x;\n"
"    }\n"
"    return $out;\n"
"}\n"
;

